    select.onchange=()=>{const row=customerRows[Number(select.value)];if(!row)return;invoiceForm.elements.customerName.value=row.name||'';invoiceForm.elements.customerPhone.value=row.phone||'';invoiceForm.elements.customerEmail.value=row.email||'';invoiceForm.dataset.customerSource=row.source;invoiceForm.dataset.customerId=row.id;};
