    host.innerHTML=`<button type="button" data-create-reminder-link>${tr('Create installment reminder preference link','إنشاء رابط لتفضيلات تذكير الأقساط')}</button><div data-reminder-link-result role="status"></div><p class="muted">${tr('The customer must opt in on this page before any email reminders can be sent.','يجب على العميل الموافقة من هذه الصفحة قبل إرسال أي تذكيرات بالبريد.')}</p>`;
