  async function decideSchedule(card,mode,csrf,id,decision){const reason=card.querySelector(`[data-schedule-note="${CSS.escape(id)}"]`)?.value||'';if(decision==='rejected'&&reason.trim().length<3){const input=card.querySelector(`[data-schedule-note="${CSS.escape(id)}"]`);input.setAttribute('aria-invalid','true');input.focus();return;}const attribute=decision==='approved'?'approve':'reject',button=card.querySelector(`[data-schedule-${attribute}="${CSS.escape(id)}"]`);button.disabled=true;try{const path=mode==='owner'?`/schedule-changes/${encodeURIComponent(id)}/decision`:`/accountant/schedule-changes/${encodeURIComponent(id)}/decision`;const body={expectedVersion:Number(card.querySelector(`[data-schedule-approve="${CSS.escape(id)}"]`)?.closest('article')?.querySelector('.badge')?.textContent.replace('v','')),decision,reason};if(mode==='owner')await legacy(path,'POST',body);else await canonical(path,'POST',body,csrf);await load();}catch(error){const alert=document.createElement('p');alert.className='error';alert.setAttribute('role','alert');alert.textContent=message(error.message);card.append(alert);button.disabled=false;}}
